/* Opt-in developer panel: ?inspectQuality=1. Never part of the ordinary HUD. */
(()=>{if(!new URLSearchParams(location.search).has('inspectQuality'))return;const panel=document.createElement('details');panel.open=true;panel.className='quality-inspector';panel.innerHTML='<summary>Диагностика графики</summary><pre aria-live="off"></pre><button type="button">Закрыть</button>';document.body.appendChild(panel);panel.querySelector('button').onclick=()=>{clearInterval(timer);panel.remove()};const timer=setInterval(()=>{const info=window.village3D?.qualityInfo?.();if(!info?.profile)return;panel.querySelector('pre').textContent=['Профиль: '+info.profile.name,'Зум: '+info.zoom.toFixed(2),'Тени: '+info.profile.shadow+'²','Лимит точечных источников: '+info.profile.lights,'Отражения: '+info.profile.reflection+' с','Вызовов в последнем проходе: '+info.drawCalls,'Треугольников в последнем проходе: '+info.triangles,'Текстур в памяти renderer: '+info.textures].join('\n')},500)})();
